changeSet.sql:
ALTER TABLE zc_ai_review
  ADD CONSTRAINT fk_zc_ai_review_tenant FOREIGN KEY (tenant_id) REFERENCES zc_tenant (id);
ALTER TABLE zc_ai_review
  ADD CONSTRAINT fk_zc_ai_review_recommendation FOREIGN KEY (tenant_id, recommendation_id)
    REFERENCES zc_ai_recommendation (tenant_id, id);

-- Tenant isolation. The app must connect as zc_app: superusers bypass RLS.
ALTER TABLE zc_ai_recommendation ENABLE ROW LEVEL SECURITY;
ALTER TABLE zc_ai_recommendation FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_zc_ai_recommendation_tenant ON zc_ai_recommendation
  USING (tenant_id = zc_current_tenant())
  WITH CHECK (tenant_id = zc_current_tenant());
ALTER TABLE zc_ai_review ENABLE ROW LEVEL SECURITY;
ALTER TABLE zc_ai_review FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_zc_ai_review_tenant ON zc_ai_review
  USING (tenant_id = zc_current_tenant())
  WITH CHECK (tenant_id = zc_current_tenant());

rollback.sql:
DROP POLICY rls_zc_ai_recommendation_tenant ON zc_ai_recommendation;
ALTER TABLE zc_ai_recommendation NO FORCE ROW LEVEL SECURITY;
ALTER TABLE zc_ai_recommendation DISABLE ROW LEVEL SECURITY;
DROP POLICY rls_zc_ai_review_tenant ON zc_ai_review;
ALTER TABLE zc_ai_review NO FORCE ROW LEVEL SECURITY;
ALTER TABLE zc_ai_review DISABLE ROW LEVEL SECURITY;

changeSet.sql:
GRANT SELECT, INSERT, UPDATE ON zc_ai_recommendation TO zc_app;
GRANT USAGE ON SEQUENCE zc_ai_recommendation_id_seq TO zc_app;
GRANT SELECT, INSERT, UPDATE ON zc_ai_review TO zc_app;
GRANT USAGE ON SEQUENCE zc_ai_review_id_seq TO zc_app;

rollback.sql:
REVOKE ALL ON zc_ai_recommendation FROM zc_app;
REVOKE USAGE ON SEQUENCE zc_ai_recommendation_id_seq FROM zc_app;
REVOKE ALL ON zc_ai_review FROM zc_app;
REVOKE USAGE ON SEQUENCE zc_ai_review_id_seq FROM zc_app;
